CREATE TABLE `expertise_items` (`id` INT NOT NULL AUTO_INCREMENT, `category` VARCHAR(40) NOT NULL, `name` VARCHAR(100) NOT NULL, `description` VARCHAR(200) NOT NULL DEFAULT '', `sort_order` INT NOT NULL DEFAULT 0, PRIMARY KEY (`id`), INDEX `expertise_items_category_sort_order_idx` (`category`, `sort_order`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE `team_members` (`id` INT NOT NULL AUTO_INCREMENT, `name` VARCHAR(120) NOT NULL, `role` VARCHAR(120) NOT NULL, `category` VARCHAR(30) NOT NULL, `expertise` TEXT NOT NULL, `modules` VARCHAR(200) NOT NULL, `technologies` VARCHAR(200) NOT NULL, `industries` VARCHAR(200) NOT NULL, `certifications` VARCHAR(300) NOT NULL, `sort_order` INT NOT NULL DEFAULT 0, PRIMARY KEY (`id`), INDEX `team_members_category_sort_order_idx` (`category`, `sort_order`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;